sources.OnlyText.ets:
export class OnlyText {
 text(): string { return `SymbolGlyph('arrow').rotate({ angle: this.expanded ? 0 : 180 }); this.expanded = !this.expanded;`; }
}

sources.Assignments.ets:
export class Assignments {
 value: string = '';
 count: number = 0;
 set(): void { this.value = 'ready'; this.count += 1; }
}

sources.QuotedWrite.ets:
export class QuotedWrite {
 text(): string { return "this.count = 2"; }
}

sources.MixedWrite.ets:
export class MixedWrite {
 count: number = 0;
 set(): void { const note = `this.fake = 3`; this.count = 1; }
}

sources.UnknownWrite.ets:
export class UnknownWrite {
 text(): string { return `this.count = 2 ${value}`; }
}

sources.Equality.ets:
export class Equality {
 count: number = 0;
 check(): boolean { return this.count === 2; }
}
